      await run;

      expect(h.frames()).toEqual([
        'upsert 0 user "hello"',
        'upsert 1 assistant ""',
        'delta 1 "first "',
        'error INVALID_MESSAGE',
        'delta 1 "second"',
        'commit 1',
        'stream_end',
      ]);
    });

    it('sends one stream_end for a three-round tool conversation', async () => {
      const call = (id: string): MessageChunk => ({type: 'tool_use', toolCall: {id, name: 'lookup', input: {id}}});
