      const h = harness([text('<thinking>half a thou')], {failWith: DROPPED});

      await h.send();

      expect({
        commits: h.frames().filter(frame => frame.startsWith('commit')),
        open: stillStreaming(h.session),
      }).toEqual({
        commits: ['commit 1'],
        open: 0,
      });
